```

FIXES.
In any case to fix the available code we need to initialize `partition_key_ops_` BEFORE it's used in `AnalyzeIndexes`.
There are several options how it's possible to do.

1. OPTION 1: Fix `PTSelectStmt::Analyze` - call `AnalyzeWhereClause` before `AnalyzeIndexes`.
Actually 1 line fix - move `AnalyzeWhereClause` upper:
WAS:
```
Status PTSelectStmt::Analyze(SemContext *sem_context) {
...
  RETURN_NOT_OK(AnalyzeSelectList(sem_context));

  if (is_top_level_) {    ...
    RETURN_NOT_OK(AnalyzeIndexes(sem_context, &scan_spec));   ...
  }

  RETURN_NOT_OK(AnalyzeWhereClause(sem_context));     <<<<< OLD PLACE

  RETURN_NOT_OK(AnalyzeIfClause(sem_context));
```
FIXED:
```
Status PTSelectStmt::Analyze(SemContext *sem_context) {
...
  RETURN_NOT_OK(AnalyzeSelectList(sem_context));

  RETURN_NOT_OK(AnalyzeWhereClause(sem_context));    <<<<<<< NEW PLACE

  if (is_top_level_) {  ...
    RETURN_NOT_OK(AnalyzeIndexes(sem_context, &scan_spec)); ...
  }

  RETURN_NOT_OK(AnalyzeIfClause(sem_context));
```
2. OPTION 2: Fix `AnalyzeReferences` - set `where_state`:
WAS:
```
Status PTSelectStmt::AnalyzeReferences(SemContext *sem_context) {
...
  if (where_clause_) {
    // Walk the <where_expr> tree, which is expected to be of BOOL type.
    SemState sem_state(sem_context, QLType::Create(BOOL), InternalType::kBoolValue);
    select_scan_info_->set_analyze_where(true);
    RETURN_NOT_OK(where_clause_->Analyze(sem_context));
```
FIXED:
```
Status PTSelectStmt::AnalyzeReferences(SemContext *sem_context) {
...
  if (where_clause_) {
    // ==============  NEW CODE BLOCK =================    <<<<<<
    // Construct the state variables and analyze the expression.
    MCVector<ColumnOp> key_where_ops(sem_context->PTempMem());
    key_where_ops.resize(IsWriteOp() ? num_key_columns() : num_hash_key_columns());
    MCVector<ColumnOpCounter> op_counters(sem_context->PTempMem());
    op_counters.resize(num_columns());
    ColumnOpCounter partition_key_counter;
    ...    // other needed variables...
    WhereExprState where_state(&where_ops, &key_where_ops, &subscripted_col_where_ops,
                               &json_col_where_ops, &partition_key_ops_, &op_counters,
                               &partition_key_counter, opcode(), &func_ops, &multi_col_where_ops);    <<< 
          <<< pass 'partition_key_ops_'
    // ==============  END OF THE NEW CODE BLOCK =================
    // Walk the <where_expr> tree, which is expected to be of BOOL type.
    SemState sem_state(sem_context, QLType::Create(BOOL), InternalType::kBoolValue);
    sem_state.SetWhereState(&where_state);       <<<< set where_state
    select_scan_info_->set_analyze_where(true);
    RETURN_NOT_OK(where_clause_->Analyze(sem_context));
```
