    RETURN_NOT_OK(AnalyzeIndexes(sem_context, &scan_spec));    ...
  }

  partition_key_ops_.clear();    <<< CLEAN - TO PREVENT DOUBLE INITIALIZATION
  RETURN_NOT_OK(AnalyzeWhereClause(sem_context));
```
